vector<long long> longestFib(const vector<long long>& a){
    int n=a.size(); map<long long, vector<int>> pos;
    for(int i=0;i<n;i++) pos[a[i]].push_back(i);
    vector<long long> best;
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
        vector<long long> cur={a[i],a[j]}; int last=j; long long x=a[i], y=a[j];
        while(true){
            auto it=pos.find(x+y); if(it==pos.end()) break;
            auto k=upper_bound(it->second.begin(),it->second.end(),last);
            if(k==it->second.end()) break;
            last=*k; cur.push_back(x+y); x=y; y=cur.back();
        }
        if(cur.size()<3) continue;
        if(cur.size()>best.size() || (cur.size()==best.size() && cur[0]<best[0])) best=cur;
    }
    return best; // empty => no valid subsequence
}
