void mergeNoExtra(vector<int>& a, vector<int>& b){
    int n=a.size(), m=b.size(), len=n+m;
    auto at=[&](int k)->int&{ return k<n ? a[k] : b[k-n]; };
    for(int gap=(len+1)/2; gap>0; gap = (gap==1?0:(gap+1)/2))
        for(int i=0;i+gap<len;i++)
            if(at(i)>at(i+gap)) swap(at(i),at(i+gap));
}

