long long threePeople(const vector<int>& X, const vector<int>& T){
    int n=X.size(); unordered_map<int,int> pos; for(int i=0;i<n;i++) pos[T[i]]=i;
    vector<int> p(n); for(int i=0;i<n;i++) p[i]=pos[X[i]];
    int pre=1; while(pre<n && p[pre]>p[pre-1]) pre++;          // Bob keeps a prefix
    int suf=1; while(suf<n && p[n-1-suf]<p[n-suf]) suf++;      // Alice keeps a suffix
    vector<int> d;                                              // Carol keeps an LIS
    for(int x:p){ auto it=lower_bound(d.begin(),d.end(),x); if(it==d.end()) d.push_back(x); else *it=x; }
    return (long long)(n-suf)+(n-pre)+(n-(int)d.size());
}

