const long long MOD=1e9+7;
long long startJump(const vector<long long>& a, const vector<pair<int,int>>& q){ // 0-based starts
    int n=a.size(), S=max(1,(int)sqrt(n)); long long total=0;
    map<int,vector<int>> small;
    for(auto [s,j]:q){
        if(j>=S){ for(int i=s;i<n;i+=j) total=(total+a[i])%MOD; }
        else small[j].push_back(s);
    }
    vector<long long> suf(n+1);
    for(auto& [j,starts]:small){
        for(int i=n-1;i>=0;i--) suf[i]=(a[i]+(i+j<n?suf[i+j]:0))%MOD;
        for(int s:starts) total=(total+suf[s])%MOD;
    }
    return total;
}

