long long maxBalanced(const vector<int>& cat, const vector<long long>& w){
    int n=cat.size(); const long long INF=LLONG_MAX; long long best=LLONG_MIN;
    set<int> cats(cat.begin(),cat.end());
    for(int c:cats){
        vector<long long> bit(2*n+3, INF);               // prefix-min BIT over shifted P
        auto upd=[&](int i,long long v){ for(;i<(int)bit.size();i+=i&-i) bit[i]=min(bit[i],v); };
        auto qry=[&](int i){ long long r=INF; for(;i>0;i-=i&-i) r=min(r,bit[i]); return r; };
        int P=n+1; long long W=0; upd(P,0);
        for(int r=0;r<n;r++){
            P += (cat[r]==c?1:-1); W += w[r];
            long long m=qry(P-1);                          // min W[l] with P[l] < P[r]
            if(m!=INF) best=max(best,W-m);
            upd(P,W);
        }
    }
    return best;
}

int binarySearch(const vector<int>& a, int x){
    int lo=0, hi=(int)a.size()-1;
    while(lo<=hi){
        int mid=lo+(hi-lo)/2;
        if(a[mid]==x) return mid;
        if(a[mid]<x) lo=mid+1; else hi=mid-1;
    }
    return -1;
}

