int firstOcc(const vector<int>& a, int x){
    int lo=0, hi=(int)a.size()-1, ans=-1;
    while(lo<=hi){
        int mid=lo+(hi-lo)/2;
        if(a[mid]==x){ ans=mid; hi=mid-1; }
