int searchInsert(vector<int>& a, int x){
    int lo=0, hi=a.size();
    while(lo<hi){ int mid=(lo+hi)/2; if(a[mid]>=x) hi=mid; else lo=mid+1; }
    if(lo<(int)a.size() && a[lo]==x) return lo;
    a.insert(a.begin()+lo, x);
