}

pair<int,int> firstLast(const vector<int>& a, int x){
    auto lb=[&](int v){ int lo=0,hi=a.size(); while(lo<hi){int m=(lo+hi)/2; if(a[m]>=v) hi=m; else lo=m+1;} return lo; };
    int f=lb(x);
    if(f==(int)a.size() || a[f]!=x) return {-1,-1};
    int l=lb(x+1)-1;          // for ints: upper_bound(x) == lower_bound(x+1)
    return {f,l};
}

int bs(const vector<int>& a, int lo, int hi, int x){
    if(lo>hi) return -1;
    int mid=lo+(hi-lo)/2;
    if(a[mid]==x) return mid;
    return a[mid]<x ? bs(a,mid+1,hi,x) : bs(a,lo,mid-1,x);
}
