long long minDryTime(const vector<long long>& X, long long K){
    long long hi=*max_element(X.begin(),X.end());
    if(K==1) return hi;
    auto ok=[&](long long T){
        long long need=0;
        for(long long x:X) if(x>T){ need+=(x-T+K-2)/(K-1); if(need>T) return false; }
        return true;
    };
    long long lo=1;
    while(lo<hi){ long long mid=lo+(hi-lo)/2; if(ok(mid)) hi=mid; else lo=mid+1; }
    return lo;
}

long long minRemove(const vector<long long>& v, long long M, long long H){
    long long pool=M*H, suf=0; int n=v.size(), k=n;
    // walk from the right while the suffix still fits in the pool
    for(int i=n-1;i>=0;i--){ if(suf+v[i]>pool) break; suf+=v[i]; k=i; }
    return k;   // villains removed from the front
}

long long minOps(const vector<long long>& a, long long A, long long B){
    auto ok=[&](long long m){
        long long need=0;
        for(long long x:a){ long long r=x-m*B;
            if(r>0){ need+=(r+(A-B)-1)/(A-B); if(need>m) return false; } }
        return true;
    };
    long long lo=0, hi=*max_element(a.begin(),a.end())/B+1;
    while(lo<hi){ long long m=(lo+hi)/2; if(ok(m)) hi=m; else lo=m+1; }
    return lo;
}

long long miniMax(const vector<vector<long long>>& g){   // needs m>=2, n>=m-1
    int n=g.size(), m=g[0].size();
    long long colPart=LLONG_MAX, rowPart=LLONG_MIN;
    for(int j=0;j<m;j++){ long long mx=LLONG_MIN;
        for(int i=0;i<n;i++) mx=max(mx,g[i][j]); colPart=min(colPart,mx); }
    for(int i=0;i<n;i++){ long long a=LLONG_MIN,b=LLONG_MIN;      // top two of the row
        for(long long v:g[i]){ if(v>a){ b=a; a=v; } else if(v>b) b=v; }
        rowPart=max(rowPart,b); }
    return min(colPart,rowPart);
}

long long fourCut(const vector<long long>& a){
    int n=a.size(); vector<long long> P(n+1,0);
    for(int i=0;i<n;i++) P[i+1]=P[i]+a[i];
    long long best=LLONG_MAX; int l=1, r=3;          // parts [0,l) [l,m) [m,r) [r,n)
    for(int m=2;m<=n-2;m++){
        while(l+1<m && llabs(P[m]-2*P[l+1]) <= llabs(P[m]-2*P[l])) l++;
        if(r<m+1) r=m+1;
        while(r+1<n && llabs(P[n]+P[m]-2*P[r+1]) <= llabs(P[n]+P[m]-2*P[r])) r++;
        long long s[4]={P[l],P[m]-P[l],P[r]-P[m],P[n]-P[r]};
        best=min(best,*max_element(s,s+4)-*min_element(s,s+4));
    }
    return best;
}

