int minK(const vector<int>& p, int m){          // p permutation of 1..n
    int n=p.size(); vector<int> at(n+1); for(int i=0;i<n;i++) at[p[i]]=i;
    auto longest=[&](int k){
        int sz=1; while(sz<n) sz<<=1; vector<int> t(2*sz,0); int best=0;
        auto qry=[&](int l,int r){ int res=0;
            for(l+=sz,r+=sz+1;l<r;l>>=1,r>>=1){ if(l&1) res=max(res,t[l++]); if(r&1) res=max(res,t[--r]); }
            return res; };
        for(int v=1;v<=n;v++){
            int i=at[v], d=1+qry(max(0,i-k),min(n-1,i+k));
            best=max(best,d); for(int x=i+sz;x;x>>=1) t[x]=max(t[x],d);
        }
        return best;
    };
    if(m<=1) return 0;
    int lo=1, hi=max(1,n-1);
    if(longest(hi)<m) return -1;
    while(lo<hi){ int mid=(lo+hi)/2; if(longest(mid)>=m) hi=mid; else lo=mid+1; }
    return lo;
}

