long long maxXorSum(const vector<long long>& a, long long K){
    const int B=31; long long n=a.size(); vector<long long> cnt(B,0);
    for(long long x:a) for(int b=0;b<B;b++) cnt[b]+=x>>b&1;
    auto val=[&](long long X){ long long s=0;
        for(int b=0;b<B;b++) s+=((X>>b&1)?n-cnt[b]:cnt[b])<<b; return s; };
    long long best=val(K);
    for(int b=B-1;b>=0;b--) if(K>>b&1){
        long long X=(K>>(b+1))<<(b+1);                  // K's high bits, bit b = 0
        for(int j=b-1;j>=0;j--) if(n-cnt[j]>cnt[j]) X|=1LL<<j;
        best=max(best,val(X));
    }
    return best;
}

