long long countXorSubsets(const vector<long long>& a, long long K){
    long long basis[62]={0}; int r=0;
    for(long long x:a){
        for(int b=61;b>=0 && x;b--) if(x>>b&1){
            if(!basis[b]){ basis[b]=x; r++; x=0; } else x^=basis[b]; }
    }
    long long k=K;
    for(int b=61;b>=0;b--) if((k>>b&1) && basis[b]) k^=basis[b];
    if(k!=0) return 0;
    long long cnt=1LL<<((int)a.size()-r);     // use modpow if n-r is large
    return K==0 ? cnt-1 : cnt;
}

long long countSuper(long long N, long long X){      // #k in [0,N] with (k&X)==X
