int maxXorHalf(const vector<int>& a){
    int n=a.size(), lim=n/2, basis[21]={0}, r=0;
    for(int x:a) for(int b=20;b>=0&&x;b--) if(x>>b&1){ if(!basis[b]){basis[b]=x;r++;x=0;} else x^=basis[b]; }
    if(r<=lim){ int res=0; for(int b=20;b>=0;b--) res=max(res,res^basis[b]); return res; }
    int h=n/2; vector<pair<int,int>> L, R;                 // (size, xor); here n <= 40
    auto gen=[&](int lo,int hi,vector<pair<int,int>>& out){ int k=hi-lo;
        for(int m=0;m<(1<<k);m++){ int x=0; for(int i=0;i<k;i++) if(m>>i&1) x^=a[lo+i];
            out.push_back({__builtin_popcount(m),x}); } };
    gen(0,h,L); gen(h,n,R); sort(R.begin(),R.end()); sort(L.rbegin(),L.rend());
    vector<array<int,2>> t(1,{0,0}); size_t p=0; int best=0;
    auto ins=[&](int x){ int nd=0; for(int b=20;b>=0;b--){ int c=x>>b&1;
        if(!t[nd][c]){ t[nd][c]=t.size(); t.push_back({0,0}); } nd=t[nd][c]; } };
    for(auto [s,x]:L){
        if(s>lim) continue;
        while(p<R.size() && R[p].first<=lim-s) ins(R[p++].second);
        int nd=0, cur=0;
        for(int b=20;b>=0;b--){ int c=x>>b&1; if(t[nd][!c]){ cur|=1<<b; nd=t[nd][!c]; } else nd=t[nd][c]; }
        best=max(best,cur);
    }
    return best;
}

