    for(int mask=1;mask<(1<<K);mask++){
        long long cost=0; bool ok=true;
        for(int i=0;i<K;i++) if(mask>>i&1) cost+=a[i];
        for(int s=0;s<S && ok && pts[s]<=N;s++){
            long long mb=LLONG_MAX; int c=cover[s]&mask;
            for(int i=0;i<K;i++) if(c>>i&1) mb=min(mb,b[i]);
            if(mb==LLONG_MAX) ok=false; else cost+=mb*(pts[s+1]-pts[s]);
        }
        if(ok) best=min(best,cost);
    }
    return best==LLONG_MAX ? -1 : best;
}

long long bestCyclic(const vector<long long>& a){   // print result % 1000000007
    int n=a.size(); long long best=0;
    for(int dir=0;dir<2;dir++){
        vector<long long> v(a); if(dir) reverse(v.begin(),v.end());
        vector<long long> P(2*n+1,0), val(n,0); vector<int> C(2*n+2,0);
        for(int i=0;i<2*n;i++) P[i+1]=P[i]^v[i%n];
        for(int b=0;b<31;b++){
            for(int i=0;i<=2*n;i++) C[i+1]=C[i]+(P[i]>>b&1);
            for(int s=0;s<n;s++){
                long long ones=C[s+n+1]-C[s+1];               // bit b set in P[s+1..s+n]
                val[s]+=((P[s]>>b&1)? n-ones : ones)<<b;
            }
        }
        for(int s=0;s<n;s++) best=max(best,val[s]);
    }
    return best;
}

pair<long long,long long> xorInverse(vector<long long> a){   // {min inversions, B}
    vector<vector<long long>> groups={a}; long long inv=0, B=0;
    for(int b=30;b>=0;b--){
        long long c0=0, c1=0; vector<vector<long long>> nxt;
        for(auto& g:groups){
            vector<long long> z,o; long long ones=0, zeros=0;
            for(long long x:g){
                if(x>>b&1){ c1+=zeros; ones++; o.push_back(x); }
                else      { c0+=ones;  zeros++; z.push_back(x); }
            }
            if(!z.empty()) nxt.push_back(move(z));
            if(!o.empty()) nxt.push_back(move(o));
        }
        if(c1<c0){ inv+=c1; B|=1LL<<b; } else inv+=c0;
        groups=move(nxt);
    }
    return {inv,B};
}

